import { ReactNode, FC } from 'react';

interface CardProps {
    /** 标题 */
    title?: ReactNode;
    /** 副标题 */
    subtitle?: ReactNode;
    /** 右侧额外内容 */
    extra?: ReactNode;
    /** 封面图 */
    cover?: string;
    /** 底部内容 */
    footer?: ReactNode;
    /** 是否显示边框 */
    bordered?: boolean;
    /** 是否有阴影 */
    shadow?: boolean;
    /** 是否可点击 */
    clickable?: boolean;
    /** 点击事件 */
    onClick?: () => void;
    /** 自定义类名 */
    className?: string;
    /** 子元素 */
    children?: ReactNode;
}

declare const Card: FC<CardProps>;

export { Card, Card as default };
export type { CardProps };
